// Get input from parent workflow
const input = $json;

// Validate required fields
if (!input.query) {
  throw new Error('Missing required field: query');
}
if (!input.api_endpoint) {
  throw new Error('Missing required field: api_endpoint');
}
if (!input.access_token) {
  throw new Error('Missing required field: access_token');
}

// Normalize api_endpoint (remove trailing slash)
const apiEndpoint = input.api_endpoint.replace(/\/$/, '');

return {
  json: {
    api_endpoint: apiEndpoint,
    access_token: input.access_token,
    api_version: input.api_version ?? '2026-01',
    body: {
      query: input.query,
      variables: input.variables ?? {}
    },
    // Retry configuration
    retry_count: input.retry_count ?? 0,
    max_retries: input.max_retries ?? 5,
    retry_on_server_error: input.retry_on_server_error ?? true
  }
};

/**
 * Comprehensive Shopify GraphQL Error Checker with Throttle Detection
 * 
 * Handles:
 * - Network errors (DNS, connection refused, timeout)
 * - HTTP errors (401, 403, 429, 500, etc.)
 * - GraphQL errors
 * - Shopify userErrors (all types)
 * - Search warnings
 * - Rate limiting / throttling
 * - Bulk operation errors
 * - Job errors
 */

const httpResponse = $json;
const prepareInput = $('Prepare Request').item.json;
const errors = [];
let needsRetry = false;
let waitSeconds = 0;
let isThrottled = false;
let isServerError = false;
let isNetworkError = false;

// ============================================
// 0. NETWORK/HTTP ERROR HANDLING
// ============================================

// Check if this is a network-level failure (no response at all)
if (httpResponse.error || httpResponse.code) {
  // Network error - no HTTP response received
  isNetworkError = true;
  isServerError = true; // Treat as server error for retry purposes
  errors.push({
    type: 'NETWORK_ERROR',
    message: httpResponse.message || httpResponse.error?.message || `Network error: ${httpResponse.code || 'Unknown'}`,
    code: httpResponse.code || null
  });
}

// Determine response structure
// fullResponse: true returns { body, headers, statusCode }
// On error with continueOnFail, might return error object
let statusCode = 200;
let response = null;
let headers = null;

if (!isNetworkError) {
  if (httpResponse.statusCode !== undefined) {
    // fullResponse format
    statusCode = httpResponse.statusCode;
    response = httpResponse.body;
    headers = httpResponse.headers;
  } else if (httpResponse.data !== undefined) {
    // GraphQL response directly (shouldn't happen with fullResponse: true)
    response = httpResponse;
  } else if (httpResponse.errors !== undefined) {
    // GraphQL response directly
    response = httpResponse;
  } else {
    // Unknown format - try to use as-is
    response = httpResponse;
  }
}

// Handle HTTP errors
if (!isNetworkError && statusCode >= 400) {
  if (statusCode === 429) {
    isThrottled = true;
    errors.push({
      type: 'HTTP_THROTTLED',
      message: 'HTTP 429 Too Many Requests',
      statusCode: statusCode
    });
    // Check Retry-After header (case-insensitive)
    const retryAfterKey = headers ? Object.keys(headers).find(k => k.toLowerCase() === 'retry-after') : null;
    if (retryAfterKey && headers[retryAfterKey]) {
      const retryAfterValue = parseInt(headers[retryAfterKey], 10);
      if (!isNaN(retryAfterValue)) {
        waitSeconds = retryAfterValue;
      }
    }
  } else if (statusCode >= 500) {
    isServerError = true;
    errors.push({
      type: 'HTTP_SERVER_ERROR',
      message: `HTTP ${statusCode} Server Error`,
      statusCode: statusCode
    });
  } else if (statusCode === 401) {
    errors.push({
      type: 'HTTP_AUTH_ERROR',
      message: 'HTTP 401 Unauthorized - Check your access token',
      statusCode: statusCode
    });
  } else if (statusCode === 403) {
    errors.push({
      type: 'HTTP_AUTH_ERROR',
      message: 'HTTP 403 Forbidden - Insufficient permissions',
      statusCode: statusCode
    });
  } else if (statusCode === 404) {
    errors.push({
      type: 'HTTP_NOT_FOUND',
      message: 'HTTP 404 Not Found - Check API endpoint',
      statusCode: statusCode
    });
  } else {
    errors.push({
      type: 'HTTP_ERROR',
      message: `HTTP ${statusCode} Error`,
      statusCode: statusCode
    });
  }
}

// ============================================
// 1. GRAPHQL ERRORS (Top Level)
// ============================================
if (response?.errors && Array.isArray(response.errors) && response.errors.length > 0) {
  for (const error of response.errors) {
    const errorInfo = {
      type: 'GRAPHQL_ERROR',
      message: error.message || 'Unknown GraphQL error',
      locations: error.locations ?? null,
      path: error.path ?? null
    };

    if (error.extensions?.code) {
      errorInfo.code = error.extensions.code;

      switch (error.extensions.code) {
        case 'THROTTLED':
          errorInfo.type = 'THROTTLED';
          isThrottled = true;
          if (typeof error.extensions.retryAfter === 'number') {
            waitSeconds = Math.max(waitSeconds, error.extensions.retryAfter);
          }
          break;
        case 'ACCESS_DENIED':
          errorInfo.type = 'ACCESS_DENIED';
          break;
        case 'INTERNAL_SERVER_ERROR':
          errorInfo.type = 'SERVER_ERROR';
          isServerError = true;
          break;
        case 'NOT_FOUND':
          errorInfo.type = 'NOT_FOUND';
          break;
      }
    }

    errors.push(errorInfo);
  }
}

// ============================================
// 2. DATA-LEVEL ERRORS (userErrors patterns)
// ============================================
const data = response?.data ?? {};

// Match any field ending in 'Errors' or 'UserErrors' for future compatibility
const isUserErrorField = (key) => {
  return key === 'userErrors' || 
         key === 'errors' ||
         key.endsWith('Errors') || 
         key.endsWith('UserErrors');
};

function findUserErrors(obj, path = '') {
  if (!obj || typeof obj !== 'object') return [];

  const foundErrors = [];

  for (const key of Object.keys(obj)) {
    const value = obj[key];
    const currentPath = path ? `${path}.${key}` : key;

    // Check for userErrors-style arrays
    if (isUserErrorField(key) && Array.isArray(value) && value.length > 0) {
      for (const userError of value) {
        if (userError && typeof userError === 'object' && userError.message) {
          foundErrors.push({
            type: 'USER_ERROR',
            category: key,
            path: currentPath,
            field: Array.isArray(userError.field) ? userError.field.join('.') : (userError.field ?? null),
            message: userError.message,
            code: userError.code ?? null
          });
        } else if (typeof userError === 'string') {
          foundErrors.push({
            type: 'USER_ERROR',
            category: key,
            path: currentPath,
            field: null,
            message: userError,
            code: null
          });
        }
      }
    }

    // Recurse into nested objects and arrays
    if (typeof value === 'object' && value !== null && !isUserErrorField(key)) {
      if (Array.isArray(value)) {
        value.forEach((item, index) => {
          if (item && typeof item === 'object') {
            foundErrors.push(...findUserErrors(item, `${currentPath}[${index}]`));
          }
        });
      } else {
        foundErrors.push(...findUserErrors(value, currentPath));
      }
    }
  }

  return foundErrors;
}

errors.push(...findUserErrors(data));

// ============================================
// 3. SEARCH WARNINGS (extensions.search)
// ============================================
const searchResults = response?.extensions?.search;
if (Array.isArray(searchResults)) {
  for (const search of searchResults) {
    if (Array.isArray(search?.warnings) && search.warnings.length > 0) {
      for (const warning of search.warnings) {
        errors.push({
          type: 'SEARCH_WARNING',
          field: warning.field ?? null,
          message: warning.message || 'Unknown search warning',
          query: search.query ?? null,
          path: Array.isArray(search.path) ? search.path.join('.') : (search.path ?? null)
        });
      }
    }
  }
}

// ============================================
// 4. COST/THROTTLE CHECK
// ============================================
const cost = response?.extensions?.cost;
let rateLimit = null;

if (cost?.throttleStatus) {
  const throttleStatus = cost.throttleStatus;

  rateLimit = {
    currentlyAvailable: throttleStatus.currentlyAvailable,
    maximumAvailable: throttleStatus.maximumAvailable,
    restoreRate: throttleStatus.restoreRate,
    requestCost: cost.requestedQueryCost,
    actualCost: cost.actualQueryCost
  };

  // Check if throttled (no points available)
  if (typeof throttleStatus.currentlyAvailable === 'number' && 
      throttleStatus.currentlyAvailable <= 0 && 
      !isThrottled) {
    isThrottled = true;
    errors.push({
      type: 'THROTTLED',
      message: 'API rate limit exceeded - no points available',
      currentlyAvailable: throttleStatus.currentlyAvailable,
      maximumAvailable: throttleStatus.maximumAvailable,
      restoreRate: throttleStatus.restoreRate
    });
  }

  // Calculate wait time if throttled
  if (isThrottled && waitSeconds === 0 && typeof throttleStatus.restoreRate === 'number' && throttleStatus.restoreRate > 0) {
    const neededPoints = ((cost.requestedQueryCost ?? 100) * 1.1);
    const secondsToWait = Math.ceil(neededPoints / throttleStatus.restoreRate);
    waitSeconds = Math.min(Math.max(secondsToWait, 2), 60);
  }
}

// ============================================
// 5. BULK OPERATION ERRORS
// ============================================
const bulkOpRunQuery = data.bulkOperationRunQuery?.bulkOperation;
if (bulkOpRunQuery?.status === 'FAILED') {
  errors.push({
    type: 'BULK_OPERATION_ERROR',
    message: bulkOpRunQuery.errorCode || 'Bulk operation failed',
    partialDataUrl: bulkOpRunQuery.partialDataUrl ?? null
  });
}

const currentBulkOp = data.currentBulkOperation;
if (currentBulkOp?.status === 'FAILED') {
  errors.push({
    type: 'BULK_OPERATION_ERROR',
    message: currentBulkOp.errorCode || 'Bulk operation failed',
    partialDataUrl: currentBulkOp.partialDataUrl ?? null
  });
}

// ============================================
// 6. JOB ERRORS
// ============================================
for (const key of Object.keys(data)) {
  const operation = data[key];
  if (operation?.job?.status === 'FAILED') {
    errors.push({
      type: 'JOB_ERROR',
      operation: key,
      message: operation.job.errorMessage || 'Async job failed'
    });
  }
}

// ============================================
// DETERMINE IF SHOULD RETRY
// ============================================
const retryCount = prepareInput.retry_count ?? 0;
const maxRetries = prepareInput.max_retries ?? 5;
const retryOnServerError = prepareInput.retry_on_server_error ?? true;

const canRetry = retryCount < maxRetries;
const shouldRetryThrottle = isThrottled && canRetry;
const shouldRetryServerError = isServerError && retryOnServerError && canRetry;
const shouldRetryNetwork = isNetworkError && canRetry;

if (shouldRetryThrottle || shouldRetryServerError || shouldRetryNetwork) {
  needsRetry = true;

  // Calculate wait time with exponential backoff if not already set
  if (waitSeconds === 0) {
    // Exponential backoff: 2, 4, 8, 16, 32 seconds (capped at 60)
    waitSeconds = Math.min(2 * Math.pow(2, retryCount), 60);
  }

  // Add jitter to prevent thundering herd (±20%)
  const jitterFactor = 1 + (0.4 * Math.random() - 0.2); // 0.8 to 1.2
  waitSeconds = Math.max(1, Math.round(waitSeconds * jitterFactor));
}

// ============================================
// BUILD RESPONSE
// ============================================
// Determine which errors are non-retryable
const retryableTypes = ['THROTTLED', 'HTTP_THROTTLED', 'SERVER_ERROR', 'HTTP_SERVER_ERROR', 'NETWORK_ERROR'];
const nonRetryableErrors = needsRetry 
  ? errors.filter(e => !retryableTypes.includes(e.type))
  : errors;

const hasNonRetryableErrors = nonRetryableErrors.length > 0;

return {
  json: {
    success: !hasNonRetryableErrors && !needsRetry,
    needsRetry: needsRetry,
    waitSeconds: waitSeconds,
    retryCount: retryCount,
    maxRetries: maxRetries,
    isThrottled: isThrottled,
    isServerError: isServerError,
    isNetworkError: isNetworkError,
    errors: errors,
    data: response?.data ?? null,
    rateLimit: rateLimit,
    statusCode: statusCode,
    // Pass through request data for retry (excluding sensitive data from error output)
    _retryData: {
      api_endpoint: prepareInput.api_endpoint,
      access_token: prepareInput.access_token,
      api_version: prepareInput.api_version,
      query: prepareInput.body.query,
      variables: prepareInput.body.variables,
      retry_count: retryCount + 1,
      max_retries: maxRetries,
      retry_on_server_error: retryOnServerError
    }
  }
};

// Prepare for retry - flatten all data needed after wait
const input = $json;
const retryData = input._retryData;

// Determine retry reason for logging
let retryReason = 'unknown';
if (input.isThrottled) retryReason = 'rate_limited';
else if (input.isNetworkError) retryReason = 'network_error';
else if (input.isServerError) retryReason = 'server_error';

return {
  json: {
    // Wait configuration
    waitSeconds: input.waitSeconds,

    // Metadata (for debugging)
    _meta: {
      retryAttempt: retryData.retry_count,
      maxRetries: retryData.max_retries,
      reason: retryReason
    },

    // All data needed to reconstruct request after wait
    // These fields match what Prepare Request expects
    api_endpoint: retryData.api_endpoint,
    access_token: retryData.access_token,
    api_version: retryData.api_version,
    query: retryData.query,
    variables: retryData.variables,
    retry_count: retryData.retry_count,
    max_retries: retryData.max_retries,
    retry_on_server_error: retryData.retry_on_server_error
  }
};

// After wait, pass data to Prepare Request
// Wait node preserves $json in latest n8n versions
const input = $json;

// Return in format expected by Prepare Request
return {
  json: {
    api_endpoint: input.api_endpoint,
    access_token: input.access_token,
    api_version: input.api_version,
    query: input.query,
    variables: input.variables,
    retry_count: input.retry_count,
    max_retries: input.max_retries,
    retry_on_server_error: input.retry_on_server_error
  }
};

// Format error message
const input = $json;

const formatError = (e) => {
  switch (e.type) {
    case 'NETWORK_ERROR':
      return `[Network] ${e.message}`;
    case 'HTTP_THROTTLED':
    case 'THROTTLED':
      return `[Throttled] ${e.message}${e.currentlyAvailable !== undefined ? ` (${e.currentlyAvailable}/${e.maximumAvailable} points)` : ''}`;
    case 'HTTP_SERVER_ERROR':
    case 'SERVER_ERROR':
      return `[Server Error] ${e.message}`;
    case 'HTTP_AUTH_ERROR':
      return `[Auth] ${e.message}`;
    case 'HTTP_NOT_FOUND':
      return `[Not Found] ${e.message}`;
    case 'HTTP_ERROR':
      return `[HTTP] ${e.message}`;
    case 'GRAPHQL_ERROR':
      return `[GraphQL] ${e.message}${e.code ? ` (${e.code})` : ''}`;
    case 'ACCESS_DENIED':
      return `[Access Denied] ${e.message}`;
    case 'NOT_FOUND':
      return `[Not Found] ${e.message}`;
    case 'USER_ERROR':
      return `[${e.category}] ${e.field ? e.field + ': ' : ''}${e.message}${e.code ? ` (${e.code})` : ''}`;
    case 'SEARCH_WARNING':
      return `[Search] ${e.field ? e.field + ': ' : ''}${e.message}${e.query ? ` (query: "${e.query}")` : ''}`;
    case 'BULK_OPERATION_ERROR':
      return `[Bulk Operation] ${e.message}`;
    case 'JOB_ERROR':
      return `[Job] ${e.operation}: ${e.message}`;
    default:
      return `[${e.type}] ${e.message}`;
  }
};

const errorSummary = input.errors.map(formatError).join('\n');

const parentWorkflow = $execution.customData.get('parentWorkflowName');
const parentWorkflowId = $execution.customData.get('parentWorkflowId');
const parentExecutionId = $execution.customData.get('parentExecutionId');

return {
  errorMessage: `Shopify API Error (HTTP ${input.statusCode}):\n${errorSummary}`,
  statusCode: input.statusCode,
  workflow: $workflow.name,
  workflowId: $workflow.id,
  executionId: $execution.id,
  parentWorkflow: parentWorkflow || null,
  parentWorkflowId: parentWorkflowId || null,
  parentExecutionId: parentExecutionId || null
};

// Return successful response
const input = $json;

return {
  json: {
    success: true,
    data: input.data,
    rateLimit: input.rateLimit,
    statusCode: input.statusCode,
    retriesUsed: input.retryCount
  }
};

json.query:
mutation CreateMetafieldDefinition($definition: MetafieldDefinitionInput!) {
  metafieldDefinitionCreate(definition: $definition) {
    createdDefinition {
      id
      key
      namespace
      name
    }
    userErrors {
      field
      message
    }
  }
}
